    (r1, c1), (r2, c2) = positions
    dr, dc = r2 - r1, c2 - c1

    # From first toward second
    rr, cc = r1, c1
    for i in range(100):
        rr += dr
        cc += dc
        if 0 <= rr < grid_rows and 0 <= cc < grid_cols:
